		if (Object.keys(agents || {}).length) for (const [_, ag] of Object.entries(agents)) try {
			const subAgent = (await ag.listAgents())[agentId];
			if (subAgent instanceof Agent) {
				agent = subAgent;
				break;
			}
		} catch (error) {
			logger.debug("Error getting agent from agent", error);
		}
