const LIST_AGENTS_ROUTE = createRoute({
	method: "GET",
	path: "/agents",
	responseType: "json",
	queryParamSchema: z.object({ partial: z.string().optional() }),
	responseSchema: listAgentsResponseSchema,
	summary: "List all agents",
	description: "Returns a list of all available agents in the system (both code-defined and stored)",
	tags: ["Agents"],
	requiresAuth: true,
	requiresPermission: MastraFGAPermissions.AGENTS_READ,
	handler: async ({ mastra, requestContext, partial }) => {
		try {
			const codeAgents = mastra.listAgents();
			const isPartial = partial === "true";
			const editor = mastra.getEditor?.();
			const logger = mastra.getLogger();
			const serializedCodeAgentsMap = await Promise.allSettled(Object.entries(codeAgents).map(async ([id, agent]) => {
				let mergedAgent = agent;
				if (editor) try {
					mergedAgent = await editor.agent.applyStoredOverrides(agent, void 0, requestContext);
				} catch {}
				return formatAgentList({
					id,
					mastra,
					agent: mergedAgent,
					requestContext,
					partial: isPartial
				});
			}));
			const serializedAgents = {};
			for (let i = 0; i < serializedCodeAgentsMap.length; i++) {
				const settled = serializedCodeAgentsMap[i];
				if (settled.status === "fulfilled") {
					const { id, ...rest } = settled.value;
					serializedAgents[id] = {
						id,
						...rest
					};
				} else {
					const agentId = Object.keys(codeAgents)[i];
					logger.warn("Failed to serialize agent", {
						agentId,
						error: settled.reason
					});
				}
			}
			try {
				const editor = mastra.getEditor();
				let storedAgentsResult;
				try {
					storedAgentsResult = await editor?.agent.list();
				} catch (error) {
					console.error("Error listing stored agents:", error);
					storedAgentsResult = null;
				}
				const codeAgentIds = /* @__PURE__ */ new Set();
				for (const [key, agent] of Object.entries(codeAgents)) {
					codeAgentIds.add(key);
					if (agent?.id) codeAgentIds.add(agent.id);
				}
				if (storedAgentsResult?.agents) for (const storedAgentConfig of storedAgentsResult.agents) {
					if (codeAgentIds.has(storedAgentConfig.id)) continue;
					try {
						const agent = await editor?.agent.getById(storedAgentConfig.id, { status: "draft" });
						if (!agent) continue;
						const serialized = await formatAgentList({
							id: agent.id,
							mastra,
							agent,
							requestContext,
							partial: isPartial
						});
						if (!serializedAgents[serialized.id]) serializedAgents[serialized.id] = serialized;
					} catch (agentError) {
						mastra.getLogger().warn("Failed to serialize stored agent", {
							agentId: storedAgentConfig.id,
							error: agentError
						});
					}
				}
			} catch (storageError) {
				mastra.getLogger().debug("Could not fetch stored agents", { error: storageError });
			}
			const fgaProvider = mastra.getServer?.()?.fga;
			const user = requestContext?.get("user");
			if (fgaProvider && user) {
				const agentList = Object.values(serializedAgents);
				const accessible = await fgaProvider.filterAccessible(user, agentList, "agent", MastraFGAPermissions.AGENTS_READ);
				const accessibleSet = new Set(accessible.map((a) => a.id));
				for (const id of Object.keys(serializedAgents)) if (!accessibleSet.has(id)) delete serializedAgents[id];
			}
			return serializedAgents;
		} catch (error) {
			return handleError(error, "Error getting agents");
		}
	}
});
